# ---
def seating_rows(students, seats_per_row):
    if seats_per_row <= 0:
        raise ValueError('seats_per_row must be positive')
    if not students:
        raise ValueError('students must not be empty')
    ordered = sorted(
        students,
        key=lambda s: (s.last_name.lower(), s.first_name.lower()),
    )
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = ' | '.join(s.display_name for s in ordered[start:start + seats_per_row])
        lines.append('Row {}: {}'.format(start // seats_per_row + 1, names))
    return lines
