cat > tests/test_seating.py <<'EOF'
import unittest

import rosterkit.models
import rosterkit.seating


def make(last, first):
    return rosterkit.models.Student(last + first, last, first, 'A')


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make('Halloway', 'Juno'),
            make('Dunmere', 'Piet'),
            make('Adair', 'Zed'),
        ]

    def test_sorted_by_last_name_and_split_into_rows(self):
        self.assertEqual(
            rosterkit.seating.seating_rows(self.students, 2),
            ['Row 1: Adair, Zed | Dunmere, Piet', 'Row 2: Halloway, Juno'],
        )

    def test_single_row_when_seats_exceed_students(self):
        lines = rosterkit.seating.seating_rows(self.students, 10)
        self.assertEqual(len(lines), 1)

    def test_same_last_name_orders_by_first_name(self):
        pair = [make('Roe', 'Sam'), make('Roe', 'Al')]
        self.assertEqual(
            rosterkit.seating.seating_rows(pair, 2), ['Row 1: Roe, Al | Roe, Sam']
        )

    def test_zero_or_negative_seats_raise(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                rosterkit.seating.seating_rows(self.students, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            rosterkit.seating.seating_rows([], 3)
